insert into articles (slug, titre, date, img, resume, contenu, created_at) values ('acheter-a-distance-confiance','Acheter sa voiture à distance en toute confiance','2026-10-02','https://images.unsplash.com/photo-1563013544-824ae1b704d3?auto=format&fit=crop&w=900&q=70','Acompte sécurisé, suivi de livraison, contrôle à la remise et rétractation : comment acheter sereinement sans vous déplacer.','["Acheter un véhicule à distance est devenu simple et sûr à condition de passer par un professionnel transparent. Chez KlarDrive, tout commence par un devis détaillé puis une signature électronique, avec un acompte sécurisé de 30 % pour réserver le véhicule.","La préparation finale comprend le contrôle des 250 points, la préparation mécanique et carrosserie ainsi qu''un nettoyage professionnel. La mise à disposition intervient sous 3 à 5 jours ouvrés, partout en Europe, avec un numéro de suivi transmis par e-mail et SMS.","Le jour de la remise, le contrôle final est effectué en votre présence. Et en cas de non-conformité majeure, l''échange ou le remboursement est immédiat, avec un délai de rétractation de 15 jours.","Une question avant de vous lancer ? Écrivez-nous par e-mail à contact@klardrive.de : réponse en moins d''une heure ouvrée."]'::jsonb,'2026-01-01T01:40:00Z');
insert into articles (slug, titre, date, img, resume, contenu, created_at) values ('documents-verifier-occasion','Occasion : les 6 documents à vérifier avant d''acheter','2026-09-26','https://images.unsplash.com/photo-1450101499163-c8848c66ca85?auto=format&fit=crop&w=900&q=70','Carte grise, non-gage, contrôle technique, carnet d''entretien : la check-list des documents qui sécurisent votre achat d''occasion.','["Un achat d''occasion serein repose d''abord sur les documents. Exigez systématiquement l'immatriculation du véhicule, le certificat de non-gage officiel et un contrôle technique de moins de 6 mois.","Demandez aussi le carnet d''entretien et l''historique du véhicule : ils prouvent le suivi et la régularité des révisions. Le certificat de cession formalise la vente, et l''attestation kilométrique garantit la conformité du compteur.","Chez KlarDrive, ces 6 documents sont fournis avec chaque véhicule, sans exception, avec un historique vérifié et un kilométrage attesté.","Un doute sur un document ? Notre équipe à Bad Homburg vor der Höhe vous répond par e-mail à contact@klardrive.de, avant, pendant et après votre achat."]'::jsonb,'2026-01-01T01:41:00Z');
insert into articles (slug, titre, date, img, resume, contenu, created_at) values ('acheter-voiture-budget','10 conseils pour acheter une bonne voiture tout en restant dans son budget','2026-09-19','https://images.unsplash.com/photo-1449965408869-eaa3f722e40d?auto=format&fit=crop&w=900&q=70','Définir un budget réaliste, comparer les modèles et miser sur l''occasion récente avec historique vérifié : le guide pour acheter sans dépasser son budget.','["Acheter une voiture nécessite une préparation rigoureuse pour éviter les mauvaises surprises financières. Il faut définir un budget réaliste en analysant revenus, dépenses fixes et variables, sans oublier assurance, entretien, carburant et réparations.","Une fois le budget établi, comparez les modèles : avis clients, fiabilité, confort et coûts d''entretien. L''occasion récente offre un excellent rapport qualité-prix grâce à une décote plus faible.","Vérifiez toujours l''historique du véhicule : entretiens, accidents, kilométrage. Négociez sur la base de la valeur réelle du marché et méfiez-vous des prix anormalement bas.","Chez KlarDrive, chaque véhicule est contrôlé et son historique vérifié : contactez-nous par e-mail à contact@klardrive.de pour être accompagné dans votre achat."]'::jsonb,'2026-01-01T01:42:00Z');
insert into articles (slug, titre, date, img, resume, contenu, created_at) values ('bien-choisir-occasion','Comment bien choisir sa voiture d''occasion ?','2026-09-19','https://images.unsplash.com/photo-1489824904134-891ab64532f1?auto=format&fit=crop&w=900&q=70','Berline, SUV ou citadine ? Fiabilité, inspection, essai routier et négociation : la méthode pour sécuriser votre achat d''occasion.','["Choisir une voiture d''occasion commence par définir ses besoins : trajets quotidiens, familiaux ou loisirs, et son budget global avec assurance, entretien et carburant.","Étudiez ensuite la fiabilité : rapports spécialisés, avis utilisateurs et classements d''experts pour évaluer durabilité et coût d''entretien de chaque modèle.","Avant l''achat, inspectez la carrosserie, les documents, le contrôle technique et l''historique, puis réalisez un essai routier pour tester maniabilité et confort.","Enfin, négociez selon la valeur marché et finalisez avec un contrat et un transfert de propriété en règle. Notre équipe à Bad Homburg vor der Höhe vous accompagne à chaque étape."]'::jsonb,'2026-01-01T01:43:00Z');
insert into articles (slug, titre, date, img, resume, contenu, created_at) values ('hybride-ou-electrique','Véhicule hybride ou électrique : que choisir ?','2026-09-19','https://images.unsplash.com/photo-1593941707882-a5bba14938c7?auto=format&fit=crop&w=900&q=70','Autonomie, coût, entretien, écologie : le comparatif pour choisir entre hybride et électrique selon votre usage quotidien et votre budget.','["Les hybrides combinent moteur thermique et électrique pour optimiser l''énergie et réduire les émissions, tandis que les électriques fonctionnent uniquement sur batterie, sans émissions à l''usage.","Les hybrides offrent plus d''autonomie et de flexibilité pour les longs trajets, avec moins de carburant qu''une essence, mais un coût d''achat plus élevé.","Les électriques affichent zéro émission, moins de carburant et moins d''entretien, mais autonomie et recharge restent des points de vigilance.","Le choix dépend de vos trajets (urbains ou longs), de votre budget, des aides disponibles et des infrastructures de recharge. Venez essayer nos modèles hybrides et électriques à Bad Homburg vor der Höhe."]'::jsonb,'2026-01-01T01:44:00Z');
insert into articles (slug, titre, date, img, resume, contenu, created_at) values ('entretenir-sa-voiture','Entretenir sa voiture : les gestes essentiels','2026-09-19','https://images.unsplash.com/photo-1487754180451-c456f719a1fc?auto=format&fit=crop&w=900&q=70','Huile, pneus, freins, entretien saisonnier : les contrôles simples qui prolongent la durée de vie, la sécurité et la valeur de votre véhicule.','["Un véhicule bien entretenu est plus sûr, plus économique et garde une meilleure valeur de revente.","Contrôlez le niveau d''huile moteur chaque mois, la pression et l''état des pneus chaque semaine, et nettoyez régulièrement intérieur et extérieur contre la corrosion.","Restez attentif aux bruits, vibrations ou voyants inhabituels. L''entretien saisonnier est essentiel : batterie et climatisation au printemps, refroidissement et freins en été, visibilité en automne, chauffage et freins en hiver.","En cas de choc ou de panne complexe, confiez votre véhicule à un professionnel pour un diagnostic et un entretien préventif. Écrivez à KlarDrive à contact@klardrive.de."]'::jsonb,'2026-01-01T01:45:00Z');
insert into articles (slug, titre, date, img, resume, contenu, created_at) values ('financement-auto-credit','Financer sa voiture : crédit 6 à 84 mois et mensualités dès 139 €','2026-10-13','assets/img/bmw-x1.jpg','Acompte de 30 %, durées de 6 à 84 mois, acceptation en 24 h : le guide du financement auto simple et sans surprise.','['Le financement auto se résume à trois chiffres : l''acompte (30 % à la réservation chez KlarDrive), la durée (de 6 à 84 mois) et la mensualité. Plus la durée est longue, plus la mensualité baisse : nos offres démarrent à 139 €/mois.','Préparez un dossier solide : pièce d''identité, justificatifs de revenus des 3 derniers mois et relevés bancaires. Une acceptation de principe arrive généralement en 24 h, sans frais cachés ni engagement.','Comparez toujours le coût total du crédit, pas seulement la mensualité : taux, assurance emprunteur et frais de dossier. Un apport plus élevé réduit le montant financé et le coût des intérêts.','Une simulation en 5 minutes ? Écrivez-nous par e-mail à contact@klardrive.de : notre équipe à Bad Homburg vor der Höhe monte votre dossier de financement.']'::jsonb,'2026-01-01T01:46:00Z');
insert into articles (slug, titre, date, img, resume, contenu, created_at) values ('garantie-occasion-jeune','Garantie auto d''occasion : 12 mois minimum et garantie constructeur','2026-10-12','assets/img/porsche-macan.jpg','Garantie légale, extension 36 mois, Herstellergarantie restante : ce qui couvre vraiment votre occasion récente en Allemagne.','['En Allemagne comme en France, tout professionnel doit garantir un véhicule d''occasion 12 mois minimum contre les vices non déclarés. C''est la base légale : exigez-la par écrit avant de signer.','Sur les véhicules de moins de 4 ans, un bonus s''ajoute : la garantie constructeur restante (Herstellergarantie). Une BMW ou Mercedes de 2023 peut encore être couverte par le constructeur : vérifiez la date de première immatriculation et le carnet d''entretien.','Chez KlarDrive, chaque véhicule affiche sa garantie : 12 mois minimum, extension possible jusqu''à 36 mois, et bénéfice de la garantie constructeur restante quand elle existe. Notre réseau de garages partenaires intervient près de votre domicile.','Vice caché ou panne après l''achat ? Notre équipe à Bad Homburg vor der Höhe vous répond par e-mail à contact@klardrive.de et organise la prise en charge.']'::jsonb,'2026-01-01T01:47:00Z');
insert into articles (slug, titre, date, img, resume, contenu, created_at) values ('livraison-domicile-hochtaunuskreis','Livraison de voiture à domicile dans le Hochtaunuskreis en 5 jours','2026-10-10','assets/img/tesla-y.jpg','Transport assuré, numéro de suivi, contrôle en votre présence : comment votre voiture arrive devant chez vous, de Bad Homburg à Königstein.','['Commander une voiture sans se déplacer, c''est possible : devis validé en ligne, signature électronique et acompte sécurisé de 30 %. Le véhicule est bloqué pour vous et la préparation finale commence aussitôt.','Dans le Hochtaunuskreis, la livraison prend 5 jours ouvrés : transport assuré et sécurisé, numéro de suivi transmis par e-mail et SMS. Nous livrons à Bad Homburg vor der Höhe, Oberursel, Friedrichsdorf, Kronberg, Königstein, Usingen et Wehrheim.','Le jour J, le contrôle final a lieu en votre présence : carrosserie, équipements, papiers et ordinateur de bord réglé en allemand. Non-conformité majeure ? Échange ou remboursement immédiat, plus 15 jours de rétractation.','Prêt à recevoir votre voiture à domicile ? Écrivez à KlarDrive à contact@klardrive.de : réponse en moins d''une heure ouvrée.']'::jsonb,'2026-01-01T01:48:00Z');
insert into articles (slug, titre, date, img, resume, contenu, created_at) values ('finitions-allemandes-premium','M Sport, AMG Line, S line : les finitions qui gardent leur valeur','2026-10-08','assets/img/audi-q3.jpg','Packs sport allemands, cuir, toit panoramique, aides à la conduite : les équipements qui protègent la revente de votre occasion récente.','['Sur le marché allemand, trois finitions dominent la demande : M Sport chez BMW, AMG Line chez Mercedes et S line chez Audi. Elles regroupent boucliers sport, jantes alliage, sièges sport et volant cuir : une voiture ainsi équipée se revend plus vite et 10 à 20 % plus cher.','Au-delà du pack, quatre options protègent la valeur : le toit panoramique, les sièges chauffants en cuir, la caméra 360° et les aides à la conduite (régulateur adaptatif, angle mort). Les boîtes automatiques sont devenues la norme attendue.','Notre stock privilégie les véhicules récents de moins de 4 ans avec ces finitions allemandes recherchées : BMW X5 M Sport, Mercedes GLC AMG Line, Audi Q3 S line. Historique vérifié, kilométrage attesté, garantie 12 mois minimum.','Vous cherchez une finition précise ? Contactez-nous par e-mail à contact@klardrive.de : nous trouvons votre modèle dans le Hochtaunuskreis et partout en Europe.']'::jsonb,'2026-01-01T01:49:00Z');
insert into articles (slug, titre, date, img, resume, contenu, created_at) values ('immatriculation-zulassung-allemagne','Zulassung : immatriculer une voiture importée en Allemagne','2026-10-06','assets/img/mercedes-glc.jpg','COC, HU, Zulassungsstelle, Kennzeichen : les 4 étapes pour immatriculer un véhicule importé, gérées par KlarDrive.','['Immatriculer un véhicule importé en Allemagne (Zulassung) exige quatre éléments : le certificat de conformité européen (COC), un contrôle technique (HU) de moins de 6 mois, une pièce d''identité avec justificatif de domicile et une attestation d''assurance (eVB-Nummer).','Le passage à la Zulassungsstelle prend ensuite quelques jours : le véhicule reçoit ses plaques (Kennzeichen) et sa carte grise allemande. Sans COC conforme, l''immatriculation est refusée : vérifiez-le avant tout achat.','Chez KlarDrive, vous n''avez rien à faire : notre service prépare le dossier COC, organise la HU et effectue les démarches en préfecture. Votre voiture est livrée à domicile dans le Hochtaunuskreis déjà immatriculée, en 5 jours.','Un doute sur les papiers d''un véhicule ? Notre équipe à Bad Homburg vor der Höhe vous répond par e-mail à contact@klardrive.de, avant, pendant et après votre achat.']'::jsonb,'2026-01-01T01:50:00Z');
insert into articles (slug, titre, date, img, resume, contenu, created_at) values ('reimport-allemagne-guide','Reimport d''Allemagne : acheter une voiture premium moins cher','2026-10-05','assets/img/bmw-m3-competition.jpg','Spécification allemande, historique vérifié, économies de 15 à 30 % : comment le reimport UE fait baisser le prix sans baisser la qualité.','['Un véhicule en reimport est une voiture neuve ou récente achetée dans un autre pays de l''UE puis immatriculée en Allemagne. Même usine, même finition M Sport ou AMG Line, même qualité : seule la filière d''achat change, et le prix baisse de 15 à 30 %.','Chez KlarDrive, tous nos reimports sont en spécification allemande : ordinateur de bord en allemand, carnet d''entretien complet et historique vérifié. Chaque véhicule passe notre contrôle de 250 points avant la mise en vente.','Les papiers européens (COC, factures, carnet) sont fournis et nous gérons la Zulassung : contrôle technique (HU), passage en préfecture et plaques. Vous recevez une voiture prête à rouler, immatriculée à Bad Homburg vor der Höhe.','Une question sur un modèle en reimport ? Écrivez-nous par e-mail à contact@klardrive.de : réponse en moins d''une heure ouvrée, devis détaillé sans engagement.']'::jsonb,'2026-01-01T01:51:00Z');
insert into articles (slug, titre, date, img, resume, contenu, created_at) values ('controle-technique-hu-allemagne','Contrôle technique en Allemagne (HU) : prix, délais et points vérifiés','2026-10-04','assets/img/vw-tiguan.jpg','Tous les 2 ans, 100 à 150 €, 160 points : tout savoir sur la Hauptuntersuchung avant d''acheter une occasion en Allemagne.','['En Allemagne, le contrôle technique s''appelle Hauptuntersuchung (HU), complété par le contrôle antipollution (AU). Il est obligatoire tous les 2 ans pour les voitures particulières et coûte entre 100 et 150 € selon l''organisme : TÜV, DEKRA, GTÜ ou KÜS.','Environ 160 points sont vérifiés : freins, éclairage, pneus, suspension, direction, corrosion du châssis et émissions. En cas de défaut grave, la vignette HU est refusée et le véhicule doit être réparé puis représenté sous un mois.','Avant d''acheter une occasion, exigez un rapport HU de moins de 6 mois : c''est la meilleure preuve de l''état réel du véhicule. Méfiez-vous des voitures vendues sans HU : elles cachent souvent des réparations coûteuses.','Chez KlarDrive, chaque véhicule est vendu avec une HU valide et un contrôle de 250 points. Une question ? Écrivez-nous à contact@klardrive.de : réponse en moins d''une heure ouvrée.']'::jsonb,'2026-01-01T01:52:00Z');
insert into articles (slug, titre, date, img, resume, contenu, created_at) values ('kilometrage-compteur-verifier','Compteur trafiqué : comment détecter une fraude au kilométrage','2026-09-30','assets/img/bmw-serie1.jpg','Usure incohérente, carnet troué, historique HU : les 5 réflexes pour repérer un kilométrage trafiqué avant d''acheter.','['La fraude au kilométrage touche encore 10 à 15 % des occasions en Europe : un compteur rabaissé de 100 000 km peut gonfler le prix de plusieurs milliers d''euros. En Allemagne, la manipulation est punissable, mais elle reste difficile à prouver après l''achat.','Cinq signaux d''alerte : usure du volant, des pédales et des sièges incohérente avec le kilométrage affiché ; carnet d''entretien incomplet ; rapports HU successifs aux kilométrages illogiques ; pneus et freins neufs sur une voiture peu roulée ; prix anormalement bas.','Exigez toujours l''historique complet : carnet tamponné, factures d''entretien, rapports HU et contrôle DEKRA ou TÜV. Un diagnostic électronique peut aussi révéler le kilométrage enregistré dans les calculateurs du moteur, de la boîte et de l''ABS.','Chez KlarDrive, le kilométrage de chaque véhicule est attesté par écrit avec historique vérifié. Un doute sur une annonce ? Notre équipe à Bad Homburg vor der Höhe vous répond par e-mail à contact@klardrive.de.']'::jsonb,'2026-01-01T01:53:00Z');
insert into articles (slug, titre, date, img, resume, contenu, created_at) values ('suv-familial-comparatif','Quel SUV familial choisir en 2026 ? X1, Q3, Tiguan, RAV 4, GLC','2026-09-23','assets/img/toyota-rav4-awd.jpg','Coffre, places, fiabilité, budget : le comparatif des 5 SUV familiaux les plus demandés, disponibles chez KlarDrive.','['Le SUV familial doit cocher quatre cases : un coffre de 500 L minimum, de vraies places arrière, une fiabilité éprouvée et un budget maîtrisé. En 2026, cinq modèles dominent les recherches : BMW X1, Audi Q3, VW Tiguan, Toyota RAV 4 et Mercedes GLC.','Le X1 et le Q3 séduisent par leurs finitions premium et leurs motorisations efficientes. Le Tiguan reste le roi du rapport espace-prix avec son coffre modulable. Le RAV 4 hybride affiche la meilleure fiabilité et la consommation la plus basse. Le GLC joue la carte du confort haut de gamme.','En occasion récente de moins de 4 ans, comptez 18 000 à 30 000 € selon le modèle et le kilométrage. Privilégiez les versions boîte automatique avec historique d''entretien constructeur complet.','Tous ces modèles sont en stock chez KlarDrive à Bad Homburg vor der Höhe, contrôlés sur 250 points et garantis 12 mois minimum. Essayez-les : écrivez à contact@klardrive.de.']'::jsonb,'2026-01-01T01:54:00Z');
insert into articles (slug, titre, date, img, resume, contenu, created_at) values ('voiture-electrique-bonus-recharge','Voiture électrique en Allemagne : bonus, recharge et vrai coût','2026-09-16','assets/img/bmw-ix3.jpg','Aides, wallbox, coût aux 100 km : ce qu''il faut calculer avant de passer à l''électrique dans le Hochtaunuskreis.','['Rouler électrique en Allemagne reste avantageux : électricité à domicile autour de 0,30 €/kWh, soit environ 6 € aux 100 km contre 12 à 15 € en essence. Ajoutez l''exonération partielle de taxe automobile (Kfz-Steuer) pour les électriques.','L''installation d''une wallbox (11 kW) coûte 1 000 à 2 500 € et recharge une batterie de 60 kWh en une nuit. Dans le Hochtaunuskreis, les bornes publiques se multiplient, mais la recharge à domicile reste deux fois moins chère.','En occasion, une électrique de 2 à 4 ans a déjà subi sa décote : c''est le meilleur rapport prix-autonomie. Vérifiez l''état de la batterie (rapport de santé, SoH) et la garantie constructeur restante, souvent de 8 ans sur la batterie.','Notre stock comprend des iX3, Tesla Model Y et EQA vérifiés avec batterie garantie. Questions sur l''autonomie réelle ? Écrivez-nous par e-mail à contact@klardrive.de.']'::jsonb,'2026-01-01T01:55:00Z');
insert into articles (slug, titre, date, img, resume, contenu, created_at) values ('boite-automatique-dsg-fiabilite','Boîte automatique DSG, 8G-DCT, Steptronic : fiabilité et entretien','2026-09-12','assets/img/mercedes-classe-a.jpg','Double embrayage, convertisseur, vidanges : comment choisir et entretenir une boîte auto d''occasion sans mauvaise surprise.','['Neuf occasions sur dix vendues chez KlarDrive sont en boîte automatique : DSG chez Volkswagen, 8G-DCT chez Mercedes, Steptronic chez BMW, S tronic chez Audi. Confort en ville, consommation optimisée : le marché a tranché.','Chaque technologie a ses règles : les doubles embrayages exigent une vidange tous les 60 000 km environ ; les boîtes à convertisseur sont plus tolérantes mais apprécient une vidange tous les 80 000 à 100 000 km. Une vidange coûte 250 à 500 € et double la durée de vie.','À l''essai, traquez les à-coups au démarrage, les patinages entre 2e et 3e et les voyants de boîte. Exigez les factures de vidange : une boîte sans entretien à 150 000 km est un risque.','Nos occasions sont diagnostiquées valise incluse, vidanges vérifiées. Un doute sur une boîte ? Écrivez à contact@klardrive.de : diagnostic avant achat possible.']'::jsonb,'2026-01-01T01:56:00Z');
insert into articles (slug, titre, date, img, resume, contenu, created_at) values ('jeune-conducteur-assurance','Jeune conducteur en Allemagne : assurance, SF-Klassen et bonnes voitures','2026-09-09','assets/img/renault-captur.jpg','Classes de bonus, conduite accompagnée, modèles pas chers à assurer : le guide du premier achat auto pour rouler serein.','['En Allemagne, l''assurance auto fonctionne par classes de bonus-malus (SF-Klassen) : un jeune conducteur démarre souvent en SF 1/2 ou SF 0, avec des tarifs élevés la première année. Chaque année sans sinistre fait grimper la classe et baisser la prime.','Le choix de la voiture change tout : une petite essence de 90 à 120 ch coûte deux fois moins cher à assurer qu''une berline puissante. Comparez la Typklasse du modèle avant d''acheter : elle détermine le tarif.','Trois astuces : assurer le véhicule au nom d''un parent avec le jeune en conducteur additionnel, choisir une franchise plus élevée, et regrouper assurance auto et habitation chez le même assureur.','Notre équipe conseille les jeunes conducteurs du Hochtaunuskreis chaque semaine : modèles économiques, assurance, financement dès 139 €/mois. Écrivez à contact@klardrive.de.']'::jsonb,'2026-01-01T01:57:00Z');
insert into articles (slug, titre, date, img, resume, contenu, created_at) values ('pneus-hiver-obligation','Pneus hiver en Allemagne : obligation, dates et budget','2026-09-05','assets/img/volvo-xc60-ultimate-t8-dark-recharge-awd.jpg','Obligation situationnelle, amende de 60 €, marquage 3PMSF : tout savoir pour rouler légal dès les premières neiges dans le Taunus.','['En Allemagne, pas de date couperet : l''obligation est situationnelle. Dès que verglas, neige fondue ou givre apparaissent, les pneus hiver sont obligatoires sous peine de 60 € d''amende et d''un point à Flensburg — et l''assurance peut refuser d''indemniser en cas d''accident.','Seuls les pneus marqués 3PMSF (flocon dans une montagne à trois pics) sont reconnus ; le simple marquage M+S ne suffit plus. Comptez 400 à 800 € le train complet monté-équilibré pour une berline ou un SUV.','Dans le Taunus, équipez-vous dès octobre : les hauteurs autour de Bad Homburg, Königstein et Usingen gèlent tôt. Vérifiez aussi la roue de secours ou le kit anti-crevaison et le niveau de lave-glace antigel.','Nos véhicules sont livrés avec des pneus contrôlés et, sur demande, un train hiver monté. Préparez l''hiver avec KlarDrive : contact@klardrive.de.']'::jsonb,'2026-01-01T01:58:00Z');
insert into articles (slug, titre, date, img, resume, contenu, created_at) values ('reprise-ancien-vehicule','Reprise de votre ancienne voiture : comment en tirer le meilleur prix','2026-09-02','assets/img/toyota-corolla.jpg','Cote, présentation, CT à jour : les 5 leviers pour maximiser la reprise de votre véhicule.','['Faire reprendre son ancienne voiture simplifie l''achat : pas d''annonces, pas d''essais avec des inconnus, et la valeur de reprise vient en déduction du prix. Mais une reprise mal préparée peut coûter 1 000 à 2 000 €.','Cinq leviers : un contrôle technique valide de moins de 6 mois ; un carnet d''entretien complet ; une présentation impeccable ; les deux clés et tous les accessoires ; et au moins deux estimations pour négocier.','Méfiez-vous des offres de reprise gonflées qui cachent une remise inexistante sur la nouvelle voiture : comparez toujours le prix net, reprise déduite. Une reprise honnête se fait sur la valeur marché réelle.','KlarDrive reprend votre véhicule au juste prix avec offre écrite en 24 h. Envoyez photos et kilométrage par e-mail à contact@klardrive.de.']'::jsonb,'2026-01-01T01:59:00Z');
insert into articles (slug, titre, date, img, resume, contenu, created_at) values ('diesel-umweltzone-vignette','Diesel et zones environnementales : vignette verte et interdictions','2026-08-28','assets/img/bmw-x1-xdrive18d.jpg','Umweltplakette, Fahrverbote, Euro 6 : peut-on encore acheter un diesel d''occasion en Allemagne en 2026 ?','['Pour entrer dans les zones environnementales de Francfort et des grandes villes, la vignette verte est obligatoire : 5 à 15 €, valable à vie du véhicule. Sans elle, 100 € d''amende.','Les interdictions de circulation visent les vieux diesels Euro 4 et moins, et localement certains Euro 5. Un diesel Euro 6 avec AdBlue reste autorisé partout et c''est le seul diesel à acheter en occasion aujourd''hui.','Le diesel garde du sens pour les gros rouleurs : 5 à 6 L/100 km sur autoroute contre 8 à 9 pour une essence équivalente, soit 1 500 € d''économie annuelle à 25 000 km/an. En dessous de 15 000 km/an, préférez l''essence ou l''hybride.','Notre stock privilégie les diesels Euro 6 récents avec vignette verte fournie. Vérifiez la norme de n''importe quel modèle par e-mail à contact@klardrive.de.']'::jsonb,'2026-01-01T01:60:00Z');
insert into articles (slug, titre, date, img, resume, contenu, created_at) values ('essai-avant-achat-checklist','Essai d''une occasion : la check-list en 15 points avant de signer','2026-08-25','assets/img/nissan-xtrail.jpg','Démarrage à froid, freinage, électronique : les 15 vérifications qui révèlent l''état réel d''une voiture.','['Un essai de 30 minutes révèle plus qu''une heure d''inspection statique : exigez un démarrage à froid, puis 15 minutes de ville et 15 minutes de voie rapide autour de Bad Homburg ou sur l''A661.','En roulant, vérifiez : direction droite sans tirer, freinage sans vibration, boîte sans à-coups, climatisation froide et chaude, tous les voyants éteints après démarrage, électronique complète et bruits suspects.','À l''arrêt : niveaux d''huile et de refroidissement, usure uniforme des pneus, jeu dans la direction, historique d''entretien et concordance des numéros entre carte grise et châssis. Refusez tout essai limité à un parking.','Chez KlarDrive, chaque essai est libre et le contrôle final a lieu en votre présence. Réservez votre essai à contact@klardrive.de.']'::jsonb,'2026-01-01T01:61:00Z');
